import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const todosPath = path.join(__dirname, 'todos.json');

function readTodos() {
  if (!existsSync(todosPath)) return [];
  try {
    const data = JSON.parse(readFileSync(todosPath, 'utf8'));
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

function nextId(todos) {
  const max = todos.reduce((m, t) => {
    const n = Number(t?.id);
    return Number.isFinite(n) && n > m ? n : m;
  }, 0);
  return max + 1;
}

function add(text) {
  const todos = readTodos();
  todos.push({ id: nextId(todos), text });
  writeFileSync(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Added: ${text}`);
}

const [command, ...args] = process.argv.slice(2);

if (command === 'add') {
  const text = args.join(' ').trim();
  if (!text) {
    console.error('Usage: node index.js add "<文本>"');
    process.exit(1);
  }
  add(text);
} else {
  console.error('Usage: node index.js add "<文本>"');
  process.exit(1);
}

