function done(id) {
  const todos = readTodos();
  const todo = todos.find((t) => Number(t?.id) === id);
  if (!todo) {
    console.error(`No todo with id ${id}.`);
    process.exit(1);
  }
  todo.done = true;
  writeFileSync(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Done: ${todo.text}`);
}

